<?php

declare(strict_types=1); namespace App\Entity\Configurator;
use App\Entity\Channel\Channel; use App\Enum\Configurator\{MultiplierType,PercentageBase,PriceType}; use App\Repository\Configurator\ConfiguratorPriceRuleRepository; use Doctrine\ORM\Mapping as ORM;
#[ORM\Entity(repositoryClass:ConfiguratorPriceRuleRepository::class)] #[ORM\Table(name:'cardnext_configurator_price_rule')] #[ORM\Index(name:'IDX_CN_CFG_RULE_LOOKUP',columns:['configurator_id','value_id','channel_id','currency_code','minimum_quantity','maximum_quantity','enabled'])]
class ConfiguratorPriceRule { #[ORM\Id,ORM\GeneratedValue,ORM\Column] private ?int $id=null; #[ORM\ManyToOne(targetEntity:Configurator::class),ORM\JoinColumn(nullable:false,onDelete:'CASCADE')] private Configurator $configurator; #[ORM\ManyToOne(targetEntity:ConfiguratorValue::class),ORM\JoinColumn(nullable:true,onDelete:'CASCADE')] private ?ConfiguratorValue $value=null; #[ORM\ManyToOne(targetEntity:Channel::class),ORM\JoinColumn(nullable:true,onDelete:'CASCADE')] private ?Channel $channel=null; #[ORM\Column(length:3)] private string $currencyCode; #[ORM\Column(length:100)] private string $chargeCode; #[ORM\Column(length:255,nullable:true)] private ?string $label=null; #[ORM\Column] private int $minimumQuantity=1; #[ORM\Column(nullable:true)] private ?int $maximumQuantity=null; #[ORM\Column(enumType:PriceType::class,length:20)] private PriceType $priceType; /** Minor units for UNIT/FIXED; basis points for PERCENT. */ #[ORM\Column(type:'bigint')] private int $amount; #[ORM\Column(enumType:MultiplierType::class,length:20)] private MultiplierType $multiplierType=MultiplierType::NONE; #[ORM\ManyToOne(targetEntity:ConfiguratorField::class),ORM\JoinColumn(nullable:true,onDelete:'CASCADE')] private ?ConfiguratorField $multiplierField=null; #[ORM\Column(enumType:PercentageBase::class,length:20,nullable:true)] private ?PercentageBase $percentageBase=null; #[ORM\Column] private int $priority=0; #[ORM\Column(options:['default'=>true])] private bool $enabled=true; #[ORM\Column(type:'datetime_immutable')] private \DateTimeImmutable $createdAt; #[ORM\Column(type:'datetime_immutable')] private \DateTimeImmutable $updatedAt;
 public function __construct(Configurator $c,string $currency,string $charge,PriceType $type,int $amount){$this->configurator=$c;$this->currencyCode=strtoupper($currency);$this->chargeCode=$charge;$this->priceType=$type;$this->amount=$amount;$this->createdAt=$this->updatedAt=new \DateTimeImmutable();} public function getId():?int{return $this->id;} public function getConfigurator():Configurator{return $this->configurator;} public function getValue():?ConfiguratorValue{return $this->value;} public function setValue(?ConfiguratorValue $v):void{$this->value=$v;} public function getChannel():?Channel{return $this->channel;} public function setChannel(?Channel $v):void{$this->channel=$v;} public function getCurrencyCode():string{return $this->currencyCode;} public function getChargeCode():string{return $this->chargeCode;} public function getLabel():?string{return $this->label;} public function setLabel(?string $v):void{$this->label=$v;} public function getMinimumQuantity():int{return $this->minimumQuantity;} public function setQuantityRange(int $min,?int $max):void{if($min<1||($max!==null&&$max<$min))throw new \InvalidArgumentException('Invalid quantity range.');$this->minimumQuantity=$min;$this->maximumQuantity=$max;} public function getMaximumQuantity():?int{return $this->maximumQuantity;} public function getPriceType():PriceType{return $this->priceType;} public function getAmount():int{return $this->amount;} public function getMultiplierType():MultiplierType{return $this->multiplierType;} public function setMultiplier(MultiplierType $type,?ConfiguratorField $field=null):void{if($type===MultiplierType::FIELD_VALUE&&$field===null)throw new \InvalidArgumentException('FIELD_VALUE requires a multiplier field.');$this->multiplierType=$type;$this->multiplierField=$field;} public function getMultiplierField():?ConfiguratorField{return $this->multiplierField;} public function getPercentageBase():?PercentageBase{return $this->percentageBase;} public function setPercentageBase(?PercentageBase $v):void{$this->percentageBase=$v;} public function getPriority():int{return $this->priority;} public function setPriority(int $v):void{$this->priority=$v;} public function isEnabled():bool{return $this->enabled;} public function setEnabled(bool $v):void{$this->enabled=$v;} public function appliesTo(int $q):bool{return $this->enabled&&$this->minimumQuantity<=$q&&($this->maximumQuantity===null||$q<=$this->maximumQuantity);} public function dimensionKey():string{return implode('|',[$this->value?->getCode()??'base',$this->chargeCode,$this->priceType->value,$this->multiplierType->value,$this->multiplierField?->getCode()??'', $this->percentageBase?->value??'']);}
}
